## solution

#### using two pointers + recursion

```cpp
#include <unordered_map>
#include <string>

std::string tokenTransform(std::string s, std::unordered_map<std::string, std::string> tokens) {
  if (tokens.count(s) > 0) {
    return tokens[s];
  }

  std::string output;
  int i = 0;
  int j = 1;
  while (i < s.length()) {
    if (s[i] != '$') {
      output += s[i];
      i += 1;
      j = i + 1;
    } else if (s[j] != '$') {
      j += 1;
    } else {
      std::string key = s.substr(i, j - i + 1);
      std::string evaluatedToken = tokenTransform(tokens[key], tokens);
      tokens[key] = evaluatedToken;
      output += evaluatedToken;
      i = j + 1;
      j = i + 1;
    }
  }
  return output;
}
```

- n = length of longest string of value
- m = # of unique tokens
- Time: ~O(n^m)
- Space: ~O(n^m)
